import{_ as e,o,c as n,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const m=JSON.parse('{"title":"Fix a mistake","description":"","frontmatter":{},"headers":[],"relativePath":"desk/fix-a-mistake.md","filePath":"desk/fix-a-mistake.md","lastUpdated":1794643263000}'),a={name:"desk/fix-a-mistake.md"};function s(d,t,i,l,c,h){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="fix-a-mistake" tabindex="-1">Fix a mistake <a class="header-anchor" href="#fix-a-mistake" aria-label="Permalink to &quot;Fix a mistake&quot;">​</a></h1><p><strong>Who:</strong> Owner or admin</p><p>Most things in the app can be corrected, but money records are never edited or deleted. Instead you reverse them, so there&#39;s always a trail. Find your mistake below.</p><table tabindex="0"><thead><tr><th>Mistake</th><th>Fix</th><th>Where</th></tr></thead><tbody><tr><td>Wrong work line</td><td>Edit or delete the line, then <strong>Save quote</strong> again</td><td>Work › Work lines</td></tr><tr><td>Wrong technician</td><td>Pick the right one, <strong>Save technicians</strong></td><td>Work › Team</td></tr><tr><td>Wrong date (car in, done, billed…)</td><td><strong>Edit dates</strong></td><td>Work › Dates</td></tr><tr><td>Wrong target date or appointment</td><td><strong>Change target date or appointment</strong></td><td>Overview</td></tr><tr><td>Wrong car or customer details</td><td><strong>More ▾ › Car</strong> or <strong>Customer</strong></td><td>Job header</td></tr><tr><td>Wrong status</td><td>Use <strong>Back to shop</strong>, <strong>Back to quote</strong> or <strong>Resume</strong></td><td>The card&#39;s status buttons</td></tr><tr><td>Invoice amount too high</td><td>Issue a <strong>credit note</strong> (below)</td><td>Pay › Invoices</td></tr><tr><td>Invoice posted by mistake</td><td><strong>Void</strong> it (below)</td><td>Pay › Invoices</td></tr><tr><td>Payment entered wrong</td><td><strong>Void</strong> the payment and record it again</td><td>Pay › Payments</td></tr><tr><td>Money must go back to the customer</td><td><strong>Refund</strong> (below)</td><td>Pay › Payments</td></tr><tr><td>Released too early</td><td>Owner presses <strong>Unlock</strong></td><td>Job header</td></tr></tbody></table><h2 id="credit-note-lower-what-an-invoice-bills" tabindex="-1">Credit note: lower what an invoice bills <a class="header-anchor" href="#credit-note-lower-what-an-invoice-bills" aria-label="Permalink to &quot;Credit note: lower what an invoice bills&quot;">​</a></h2><ol><li>On <strong>Pay › Invoices</strong>, press <strong>Credit</strong> on the posted invoice.</li><li>Enter the amount (including VAT), the date and a reason, then issue it.</li><li><strong>Print</strong> the credit note for the customer or insurer.</li></ol><p>No money moves. Balances, receivables and commission go down. <strong>Void credit</strong> reverses it.</p><h2 id="refund-give-money-back" tabindex="-1">Refund: give money back <a class="header-anchor" href="#refund-give-money-back" aria-label="Permalink to &quot;Refund: give money back&quot;">​</a></h2><ol><li>On <strong>Pay › Payments</strong>, press <strong>Refund</strong> on the payment.</li><li>Enter the amount, method, the shop account it came from, the date, a reference and a reason.</li><li>Save. <strong>Void refund</strong> undoes a refund entered by mistake.</li></ol><h2 id="void-an-invoice" tabindex="-1">Void an invoice <a class="header-anchor" href="#void-an-invoice" aria-label="Permalink to &quot;Void an invoice&quot;">​</a></h2><p>Press <strong>Void</strong> on the invoice and give a reason. If it has credit notes or refunds, void those first.</p><h2 id="unlock-a-released-job" tabindex="-1">Unlock a released job <a class="header-anchor" href="#unlock-a-released-job" aria-label="Permalink to &quot;Unlock a released job&quot;">​</a></h2><p>Owner only. Press <strong>Unlock</strong> in the job header. The old release is kept as <strong>Previous release</strong> history so you can see what changed. Release the car again when you&#39;re done.</p><div class="warning custom-block"><p class="custom-block-title">Closed months</p><p>Once the owner closes a month (<strong>Finance › Month close</strong>), money in that month can&#39;t be changed. Corrections go in the current month.</p></div>',14)])])}const u=e(a,[["render",s]]);export{m as __pageData,u as default};
